import{_ as n,o as t,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Admin Plan Editor — spec","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-plan-editor/spec.md","filePath":"feature/admin-plan-editor/spec.md"}'),c={name:"feature/admin-plan-editor/spec.md"};function h(o,i,d,l,r,g){return t(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="admin-plan-editor-—-spec" tabindex="-1">Admin Plan Editor — spec <a class="header-anchor" href="#admin-plan-editor-—-spec" aria-label="Permalink to &quot;Admin Plan Editor — spec&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Admin chỉnh giá, hạn mức và trạng thái mở bán của 6 gói (BASIC, PLUS, ENTERPRISE, STUDIO_FREE, STUDIO_PLUS, STUDIO_PRO) ngay trên web, không cần viết migration SQL. Landing đọc bảng giá từ hệ thống thay vì ghi cứng.</p><h2 id="user-story" tabindex="-1">User Story <a class="header-anchor" href="#user-story" aria-label="Permalink to &quot;User Story&quot;">​</a></h2><p>Là <strong>Admin</strong>, tôi muốn tăng/giảm AI Credit, dung lượng, số workspace… hoặc đổi giá của một gói và ghi lý do, để vận hành điều chỉnh gói theo chi phí thực tế mà không làm ảnh hưởng khách đã trả tiền.</p><h2 id="quyet-đinh-nghiep-vu-đa-chot-voi-chu-du-an-2026-11-22" tabindex="-1">Quyết định nghiệp vụ (đã chốt với chủ dự án 2026-11-22) <a class="header-anchor" href="#quyet-đinh-nghiep-vu-đa-chot-voi-chu-du-an-2026-11-22" aria-label="Permalink to &quot;Quyết định nghiệp vụ (đã chốt với chủ dự án 2026-11-22)&quot;">​</a></h2><ol><li>Sửa gói = tạo <strong>phiên bản gói mới</strong>. Khách đang dùng giữ phiên bản cũ đến hết kỳ đã trả.</li><li>Mua mới <strong>và gia hạn</strong> nhận phiên bản mới nhất (luồng đặt hàng hiện có đã chọn bản <code>is_sellable</code> mới nhất).</li><li>Admin sửa được: hạn mức, giá tháng, giá trả trước 3/6/12 tháng, bật/tắt bán.</li><li>Mỗi thay đổi bắt buộc nhập lý do; lưu người sửa, thời điểm, lý do; xem lại các phiên bản cũ.</li><li>Landing + trang chọn gói đọc giá/hạn mức từ API.</li></ol><h2 id="acceptance-criteria" tabindex="-1">Acceptance Criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance Criteria&quot;">​</a></h2><ul><li>AC1 Trang <code>/admin?view=plans</code> liệt kê 6 gói theo 2 dòng (Studio / Agency): phiên bản hiện tại, giá tháng, giá 3/6/12, các hạn mức, trạng thái mở bán, số khách đang ở phiên bản đó.</li><li>AC2 Sửa gói: form chứa giá trị hiện tại; lưu tạo version = max+1, các phiên bản cũ thôi bán, trạng thái mở bán giữ như bản trước. Không đổi gì → lỗi &quot;không có thay đổi&quot;.</li><li>AC3 Gói miễn phí (BASIC, STUDIO_FREE): giá cố định 0, không có giá trả trước. Gói trả phí: giá tháng &gt; 0 và đủ 3 giá 3/6/12 &gt; 0.</li><li>AC4 Hai admin cùng sửa: người lưu sau nhận lỗi xung đột phiên bản (gửi <code>expectedVersion</code>).</li><li>AC5 Bật/tắt bán chỉ đổi cờ trên bản mới nhất, cần lý do, được ghi lịch sử. Tắt bán → trang chọn gói không cho thanh toán gói đó; khách đang dùng không đổi.</li><li>AC6 Lịch sử: danh sách phiên bản (mới → cũ) + các thay đổi (hành động, người sửa, thời điểm, lý do).</li><li>AC7 Khách đang dùng phiên bản cũ: hạn mức, credit hàng tháng, dung lượng gói miễn phí, quota newsletter tiếp tục theo phiên bản cũ.</li><li>AC8 Landing hiển thị giá/hạn mức từ <code>GET /api/v1/public/billing/plans?line=STUDIO|AGENCY</code> (không cần đăng nhập, giới hạn theo IP).</li><li>AC9 i18n: key mới thêm song song <code>vi</code> + <code>en</code> (<code>admin.plans.*</code>, <code>landing.pricing.*</code>). Không chuỗi cứng trong JSX.</li><li>AC10 Light/Dark: chỉ dùng token/biến theme và <code>dark:</code> variant có sẵn.</li></ul><h2 id="api-contract" tabindex="-1">API Contract <a class="header-anchor" href="#api-contract" aria-label="Permalink to &quot;API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Quyền</th><th>Mô tả</th></tr></thead><tbody><tr><td>GET</td><td><code>/api/v1/admin/billing/plans</code></td><td>Admin</td><td>6 gói, bản mới nhất + số khách</td></tr><tr><td>PUT</td><td><code>/api/v1/admin/billing/plans/{code}</code></td><td>Admin</td><td>Tạo phiên bản mới</td></tr><tr><td>POST</td><td><code>/api/v1/admin/billing/plans/{code}/sale</code></td><td>Admin</td><td><code>{ sellable, reason }</code></td></tr><tr><td>GET</td><td><code>/api/v1/admin/billing/plans/{code}/history</code></td><td>Admin</td><td>Phiên bản + nhật ký</td></tr><tr><td>GET</td><td><code>/api/v1/public/billing/plans?line=</code></td><td>Guest</td><td>Catalog một dòng gói</td></tr></tbody></table><p>PUT body: <code>expectedVersion, priceMonthly, cyclePrices{3,6,12}, maxActiveWorkspaces, maxInternalMembers, maxClients, storageLimitBytes, monthlyAiCredits, maxConcurrentAiJobs, versionRetentionDays, trashRetentionDays, activityRetentionDays, newsletterEmailQuota, reason</code>.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><ul><li><code>PLAN_NOT_FOUND</code> (404) mã gói không hợp lệ.</li><li><code>PLAN_VERSION_CONFLICT</code> (409) <code>expectedVersion</code> khác bản mới nhất.</li><li><code>PLAN_UNCHANGED</code> (400) không có trường nào đổi.</li><li><code>VALIDATION_ERROR</code> (400) giá/hạn mức sai quy tắc AC3 hoặc ngoài giới hạn.</li></ul><h2 id="edge-cases" tabindex="-1">Edge Cases <a class="header-anchor" href="#edge-cases" aria-label="Permalink to &quot;Edge Cases&quot;">​</a></h2><ul><li>Enterprise vốn không bán qua SePay (<code>Liên hệ sales</code>): bật bán chỉ đổi cờ, checkout vẫn không mở.</li><li>Gói miễn phí: khách hiện có không bao giờ &quot;gia hạn&quot; nên giữ phiên bản cũ; công ty mới / hết hạn rơi về bản mới.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><p>Mobile app; thêm/xóa gói mới; đổi tên gói; báo cáo SRS (Report 3–7).</p><ul><li>Gói miễn phí <strong>không được tắt bán</strong>: công ty mới được gán bản miễn phí <code>is_sellable</code> mới nhất (<code>AgencyServiceImpl</code>), tắt bán sẽ làm đăng ký công ty lỗi → <code>PLAN_SALE_LOCKED</code> (400).</li></ul>',19)])])}const m=n(c,[["render",h]]);export{p as __pageData,m as default};
